        res.push_back(i);
    return res;
}

struct Entry {
    string name;
    int number;
};

ostream& operator<<(ostream& os, const Entry& e)
{
    return os << "{\"" << e.name << "\", " << e.number << "}";
}

istream& operator>>(istream& is, Entry& e)
    // { "이름" ,번호 } 쌍 읽기. { " " , 와 } 로 형식화됨
{
    char c, c2;
    if (is>>c && c=='{' && is>>c2 && c2=='"') { // { "로 시작
        string name;                            // string의 기본 값은 빈 문자열: ""
        while (is.get(c) && c!='"')              // " 이전의 모든 문자는 이름으로 저장
            name+=c;

        if (is>>c && c==',') {
            int number = 0;
            if (is>>number>>c && c=='}') {        // 번호와 } 읽기
                e = {name, number};              // 항목에 대입
                return is;
            }
        }
    }
    is.setstate(ios_base::failbit);              // 스트림에 실패를 기록함
    return is;
}

